cases.cmd:
R=$(mktemp -d /tmp/claude-evalrepo-XXXXXX)/mh-{{SID}}
mkdir -p $R/.claude/evals/cases
printf '%s' '{"cases": [{"name": "h", "hook": "hooks/no-such-hook.sh", "input": {}, "expect": {"decision": "none"}}]}' > $R/.claude/evals/cases/c.json
bash {{KIT}}/evals/run.sh $R/.claude/evals/cases/c.json | tail -2; echo rc=${PIPESTATUS[0]}
rm -rf $(dirname $R)

R=$(mktemp -d /tmp/claude-evalrepo-XXXXXX)/sk-{{SID}}
mkdir -p $R/.claude/evals/cases
printf '%s' '{"cases": [{"name": "t", "requires": ["cctoolkit-no-such-command"], "cmd": "true", "expect": {"exit": 0}}]}' > $R/.claude/evals/cases/c.json
bash {{KIT}}/evals/run.sh $R/.claude/evals/cases/c.json | tail -2; echo rc=${PIPESTATUS[0]}
rm -rf $(dirname $R)

R=$(mktemp -d /tmp/claude-evalrepo-XXXXXX)/st-{{SID}}
mkdir -p $R/.claude/evals/cases
printf '%s' '{"cases": [{"name": "t", "requires": ["cctoolkit-no-such-command"], "cmd": "true", "expect": {"exit": 0}}]}' > $R/.claude/evals/cases/c.json
CCTOOLKIT_EVALS_STRICT=1 bash {{KIT}}/evals/run.sh $R/.claude/evals/cases/c.json | tail -2; echo rc=${PIPESTATUS[0]}
rm -rf $(dirname $R)
